const inputItems = $input.all();

function parseResult(item) {
  const json = item.json;

  const candidate =
    json.output ??
    json.text ??
    json.response ??
    json.result;

  if (
    candidate &&
    typeof candidate === "object"
  ) {
    return candidate;
  }

  if (typeof candidate === "string") {
    try {
      return JSON.parse(candidate);
    } catch {
      return {
        raw: candidate,
        parseError: true,
      };
    }
  }

  return {
    raw: json,
    parseError: true,
  };
}

const partialResults = inputItems.map(
  (item, index) => ({
    chunkIndex: index + 1,
    result: parseResult(item),
  }),
);

// 直接从前面的标准化节点读取论文元数据，
// 不依赖AI节点是否保留了输入字段。
const normalized =
  $("Normalize Input").first().json;

return [
  {
    json: {
      requestId: normalized.requestId,
      paper: normalized.paper,
      contentMeta: {
        source: normalized.content.source,
        originalCharCount:
          normalized.content.originalCharCount,
        normalizedCharCount:
          normalized.content.normalizedCharCount,
        wasTruncated:
          normalized.content.wasTruncated,
      },
      output: normalized.output,
      chunkCount: partialResults.length,
      partialResults,
    },
  },
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const incoming = $input.first().json;

// Webhook真实请求的数据通常在body中；
// Pin Data或手动测试时也允许直接传入JSON。
const root =
  incoming.body &&
  typeof incoming.body === "object" &&
  !Array.isArray(incoming.body)
    ? incoming.body
    : incoming;

const item = root.item ?? {};
const content = root.content ?? {};
const inputOptions = root.options ?? {};

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  if (typeof value === "string") {
    return value.trim();
  }

  return String(value).trim();
}

function normalizeAuthors(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((author) => {
      if (typeof author === "string") {
        return author.trim();
      }

      if (!author || typeof author !== "object") {
        return "";
      }

      // 兼容Zotero可能发送的多种作者结构
      const fullName = [
        toText(author.firstName),
        toText(author.lastName),
      ]
        .filter(Boolean)
        .join(" ")
        .trim();

      return (
        fullName ||
        toText(author.name) ||
        toText(author.literal)
      );
    })
    .filter(Boolean);
}

function normalizeTags(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((tag) => {
      if (typeof tag === "string") {
        return tag.trim();
      }

      if (tag && typeof tag === "object") {
        return toText(tag.tag);
      }

      return "";
    })
    .filter(Boolean);
}

function cleanText(value) {
  return toText(value)
    .replace(/\u0000/g, "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .trim();
}

function sanitizeFilename(value) {
  return toText(value)
    // Windows非法文件名字符
    .replace(/[<>:"/\\|?*\u0000-\u001F]/g, "-")
    .replace(/\s+/g, " ")
    .replace(/-+/g, "-")
    .replace(/[. ]+$/g, "")
    .trim();
}

function normalizeSubfolder(value) {
  return toText(value)
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
}

const title = toText(item.title);
const itemKey = toText(item.itemKey);
const abstract = cleanText(item.abstract);
const authors = normalizeAuthors(
  item.authors ?? item.creators ?? [],
);
const tags = normalizeTags(item.tags ?? []);

const rawDate = toText(item.year || item.date);
const yearMatch = rawDate.match(/\b(19|20)\d{2}\b/);
const year = yearMatch ? yearMatch[0] : "未注明年份";

let source = toText(content.source);
let originalText = cleanText(content.text);

// 没有正文时自动使用摘要
if (!originalText && abstract) {
  originalText = abstract;
  source = "abstract";
}

if (!source && originalText) {
  source = "unknown";
}

// 限制极端长文本，避免一次执行消耗过多Token。
// 普通论文一般不会超过这个限制。
const requestedMaxChars = Number(inputOptions.maxChars);
const maxChars =
  Number.isFinite(requestedMaxChars) &&
  requestedMaxChars >= 10000 &&
  requestedMaxChars <= 500000
    ? requestedMaxChars
    : 160000;

let normalizedText = originalText;
let wasTruncated = false;

if (originalText.length > maxChars) {
  wasTruncated = true;

  // 保留开头、中间和结尾，比简单截断结尾更合理
  const firstLength = Math.floor(maxChars * 0.5);
  const middleLength = Math.floor(maxChars * 0.25);
  const lastLength =
    maxChars - firstLength - middleLength;

  const middleStart = Math.max(
    0,
    Math.floor(originalText.length / 2 - middleLength / 2),
  );

  normalizedText = [
    originalText.slice(0, firstLength),
    "\n\n[因原文过长，中间部分经过抽样]\n\n",
    originalText.slice(
      middleStart,
      middleStart + middleLength,
    ),
    "\n\n[因原文过长，跳转至结尾部分]\n\n",
    originalText.slice(-lastLength),
  ].join("");
}

const errors = [];

if (!itemKey) {
  errors.push("缺少item.itemKey");
}

if (!title) {
  errors.push("缺少item.title");
}

if (!normalizedText) {
  errors.push("论文正文和摘要均为空");
}

if (normalizedText && normalizedText.length < 50) {
  errors.push("可分析文本少于50个字符");
}

const firstAuthor = authors[0] || "未知作者";

const safeTitle =
  sanitizeFilename(title || "未命名论文").slice(0, 80);

const safeAuthor =
  sanitizeFilename(firstAuthor).slice(0, 30);

const baseFilename = sanitizeFilename(
  `${year}-${safeAuthor}-${safeTitle}`,
);

const filename = `${baseFilename}.md`;

const subfolder =
  normalizeSubfolder(inputOptions.subfolder) ||
  "Literature Notes";

const requestId =
  toText(root.requestId) ||
  `n8n-${String($execution.id)}`;

const chunkSizeInput = Number(inputOptions.chunkSize);
const overlapInput = Number(inputOptions.chunkOverlap);

const chunkSize =
  Number.isFinite(chunkSizeInput) &&
  chunkSizeInput >= 4000 &&
  chunkSizeInput <= 30000
    ? chunkSizeInput
    : 12000;

const chunkOverlap =
  Number.isFinite(overlapInput) &&
  overlapInput >= 0 &&
  overlapInput <= 2000
    ? overlapInput
    : 600;

return [
  {
    json: {
      valid: errors.length === 0,
      errors,

      requestId,

      paper: {
        itemKey,
        title,
        authors,
        authorText: authors.join(", "),
        year,
        date: toText(item.date),
        doi: toText(item.doi),
        url: toText(item.url),
        publicationTitle: toText(
          item.publicationTitle,
        ),
        abstract,
        tags,
      },

      content: {
        source,
        text: normalizedText,
        originalCharCount: originalText.length,
        normalizedCharCount: normalizedText.length,
        wasTruncated,
      },

      options: {
        template:
          toText(inputOptions.template) ||
          "academic_reading_v1",
        language:
          toText(inputOptions.language) || "zh-CN",
        maxChars,
        chunkSize,
        chunkOverlap,
        subfolder,
      },

      output: {
        filename,
        relativePath: `${subfolder}/${filename}`,
      },

      receivedAt: new Date().toISOString(),
    },
  },
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const base = $input.first().json;

const text = base.content.text;
const chunkSize = base.options.chunkSize;
const overlap = base.options.chunkOverlap;

const chunks = [];

let start = 0;

while (start < text.length) {
  let end = Math.min(
    start + chunkSize,
    text.length,
  );

  // 尽量在段落边界切分，而不是直接切断句子
  if (end < text.length) {
    const paragraphBreak = text.lastIndexOf(
      "\n\n",
      end,
    );

    const sentenceBreak = Math.max(
      text.lastIndexOf("。", end),
      text.lastIndexOf(".", end),
      text.lastIndexOf("！", end),
      text.lastIndexOf("？", end),
    );

    const minimumAcceptableEnd =
      start + Math.floor(chunkSize * 0.65);

    if (paragraphBreak > minimumAcceptableEnd) {
      end = paragraphBreak;
    } else if (sentenceBreak > minimumAcceptableEnd) {
      end = sentenceBreak + 1;
    }
  }

  const chunkText = text
    .slice(start, end)
    .trim();

  if (chunkText) {
    chunks.push(chunkText);
  }

  if (end >= text.length) {
    break;
  }

  const nextStart = Math.max(
    end - overlap,
    start + 1,
  );

  start = nextStart;
}

return chunks.map((chunkText, index) => ({
  json: {
    requestId: base.requestId,
    paper: base.paper,
    output: base.output,

    contentMeta: {
      source: base.content.source,
      originalCharCount:
        base.content.originalCharCount,
      normalizedCharCount:
        base.content.normalizedCharCount,
      wasTruncated:
        base.content.wasTruncated,
    },

    chunkIndex: index + 1,
    chunkCount: chunks.length,
    chunkText,
  },
}));

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const input = $input.first().json;

function parseResult(json) {
  const candidate =
    json.output ??
    json.text ??
    json.response ??
    json.result;

  if (
    candidate &&
    typeof candidate === "object"
  ) {
    return candidate;
  }

  if (typeof candidate === "string") {
    return JSON.parse(candidate);
  }

  throw new Error("无法识别AI总结结果");
}

function yamlQuote(value) {
  return `"${String(value ?? "")
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\r?\n/g, " ")}"`;
}

function textOrFallback(value) {
  const text = String(value ?? "").trim();

  return text || "原文未明确说明。";
}

function bulletList(value) {
  if (!Array.isArray(value) || value.length === 0) {
    return "- 原文未明确说明";
  }

  return value
    .filter(Boolean)
    .map((item) => `- ${String(item).trim()}`)
    .join("\n");
}

const result = parseResult(input);

const normalized =
  $("Normalize Input").first().json;

const aggregate =
  $("Aggregate Chunks").first().json;

const paper = normalized.paper;

const authorsYaml =
  paper.authors.length > 0
    ? paper.authors
        .map(
          (author) =>
            `  - ${yamlQuote(author)}`,
        )
        .join("\n")
    : `  - "未知作者"`;

const tags = Array.from(
  new Set([
    "文献笔记",
    "AI精读",
    ...paper.tags,
    ...(result.keywords ?? []),
  ]),
);

const tagsYaml = tags
  .map((tag) => `  - ${yamlQuote(tag)}`)
  .join("\n");

const generatedAt = new Date().toISOString();

const markdown = `---
title: ${yamlQuote(paper.title)}
authors:
${authorsYaml}
year: ${yamlQuote(paper.year)}
doi: ${yamlQuote(paper.doi)}
zotero_key: ${yamlQuote(paper.itemKey)}
source: ${yamlQuote(normalized.content.source)}
generated_at: ${yamlQuote(generatedAt)}
tags:
${tagsYaml}
---

# ${paper.title}

## 一句话总结

${textOrFallback(result.oneSentenceSummary)}

## 研究背景

${textOrFallback(result.background)}

## 核心问题

${textOrFallback(result.researchQuestion)}

## 研究方法

${textOrFallback(result.method)}

## 数据与实验设计

${textOrFallback(result.dataAndExperiments)}

## 主要结论

${bulletList(result.findings)}

## 创新与贡献

${bulletList(result.contributions)}

## 局限性

${bulletList(result.limitations)}

## 未来展望

${bulletList(result.futureWork)}

## 不确定或原文未说明的信息

${bulletList(result.uncertainties)}

## 原始信息

- 作者：${paper.authorText || "未知作者"}
- 年份：${paper.year}
- 期刊：${paper.publicationTitle || "未注明"}
- DOI：${paper.doi || "未注明"}
- Zotero Key：${paper.itemKey}
- 分析来源：${normalized.content.source}
- 分段数量：${aggregate.chunkCount}
- 是否截断：${normalized.content.wasTruncated ? "是" : "否"}

## 我的思考

- 
`;

return [
  {
    json: {
      requestId: normalized.requestId,
      itemKey: paper.itemKey,
      title: paper.title,
      filename: normalized.output.filename,
      relativePath:
        normalized.output.relativePath,
      markdown,

      metrics: {
        source: normalized.content.source,
        inputChars:
          normalized.content.normalizedCharCount,
        chunkCount: aggregate.chunkCount,
        wasTruncated:
          normalized.content.wasTruncated,
      },
    },
  },
];

parameters.responseBody:
={{
  {
    success: true,
    requestId: $json.body.requestId,
    itemKey: $json.body.item.itemKey,
    message: `已收到论文：${$json.body.item.title}`
  }
}}
